{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Salicylic acid, a small aromatic acid/enol with intramolecular hydrogen bonding, has near-complete absolute bioavailability (0.97) in humans; this strongly supports high oral bioavailability for the acidic 4-hydroxycoumarin-like query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "4-Phenylbutyric acid, an aromatic carboxylic acid, has an absolute oral bioavailability of 78% in humans, supporting high F for the lipophilic aromatic acid-like query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Vorinostat, a lipophilic aromatic hydroxamic acid/amide, has about 43% oral bioavailability in humans, well above the 20% threshold, supporting a high-F prediction for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Diphenhydramine, a lipophilic aromatic drug, shows systemic availability of 0.69 after oral dosing in humans, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Labetalol has a reported absolute bioavailability of 18% in humans, below the threshold, but this low F is attributed to extensive first-pass metabolism of a basic aryl ethanolamine, a liability not shared by the acidic 4-hydroxycoumarin query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a lipophilic 4-hydroxycoumarin (phenprocoumon-like) with an acidic enol and no basic center. The most mechanistically relevant analogues—salicylic acid and 4-phenylbutyric acid—show high oral bioavailability (78–97%), and several other lipophilic aromatic drugs exceed the 20% threshold. The only sub-threshold evidence, labetalol, is not transferable because its low F arises from first-pass metabolism of a basic amine-containing structure. Overall, the evidence supports high oral bioavailability.",
  "evidence_gaps": [
    "No direct experimental bioavailability record for the query molecule was provided; the prediction relies on transferable analogues.",
    "The supplied transfer scores are uniformly high and do not by themselves discriminate structural or mechanistic relevance, so chemical reasoning was used to weight the evidence.",
    "Labetalol's low bioavailability is mechanistically non-transferable to the query, but no direct query-specific metabolic or absorption data were available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

